interface AjvErrorLike {
  keyword: string;
  instancePath?: string;
  dataPath?: string;
  params: object;
  message?: string;
}

interface ValidationFailure {
  fieldPath: string;
  keyword: string;
  summary: string;
}

function compileToolSchema(ajv: AjvInstance, toolName: string, schema: Record<string, unknown>): ValidateFunction {
  try {
    return ajv.compile(schema);
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : String(error);
    throw new Error(`Invalid inputSchema for tool "${toolName}": ${errorMessage}`, {cause: error});
  }
}

function formatRejectionMessage(toolName: string, failures: ValidationFailure[]): string {
  const details = failures.map(failure => failure.summary).join('; ');
  return `Input validation failed for tool "${toolName}": ${details}`;
}

function describeValidationFailures(schemaErrors: AjvErrorLike[]): ValidationFailure[] {
  return schemaErrors.map(describeAjvError);
}

function describeAjvError(schemaError: AjvErrorLike): ValidationFailure {
  const summary = formatKeywordFailure(schemaError);
  const fieldPath = formatFailurePath(schemaError);
  return {fieldPath, keyword: schemaError.keyword, summary};
}

function formatKeywordFailure(schemaError: AjvErrorLike): string {
  if (schemaError.keyword === 'required') return formatRequiredFailure(schemaError);
  if (schemaError.keyword === 'type') return formatTypeFailure(schemaError);
  if (schemaError.keyword === 'enum') return formatEnumFailure(schemaError);
  const fieldPath = formatFieldPath(schemaError);
  return `${fieldPath}: ${schemaError.message ?? `failed ${schemaError.keyword} constraint`}`;
}

function formatFailurePath(schemaError: AjvErrorLike): string {
  if (schemaError.keyword === 'required') return formatRequiredPath(schemaError);
  return formatFieldPath(schemaError);
}

function formatRequiredFailure(schemaError: AjvErrorLike): string {
  const targetPath = formatRequiredPath(schemaError);
  return `missing required property '${targetPath}'`;
}

function formatTypeFailure(schemaError: AjvErrorLike): string {
  const fieldPath = formatFieldPath(schemaError);
  const rawType = 'type' in schemaError.params ? schemaError.params.type : undefined;
  const expectedType = formatExpectedType(rawType);
  return `property '${fieldPath}' must be of type ${expectedType}`;
}

function formatExpectedType(rawType: unknown): string {
  if (Array.isArray(rawType)) return rawType.join(' | ');
  const typeText = String(rawType);
  return typeText.split(',').join(' | ');
}

function formatEnumFailure(schemaError: AjvErrorLike): string {
  const fieldPath = formatFieldPath(schemaError);
  const allowed = 'allowedValues' in schemaError.params ? schemaError.params.allowedValues : undefined;
  if (!Array.isArray(allowed)) return `property '${fieldPath}' must match one of the allowed values`;
  const choices = allowed.map(choice => JSON.stringify(choice)).join(', ');
  return `property '${fieldPath}' must be one of the allowed values (${choices})`;
}

function formatRequiredPath(schemaError: AjvErrorLike): string {
  const basePath = formatFieldPath(schemaError);
  const missingProperty = 'missingProperty' in schemaError.params ? schemaError.params.missingProperty : undefined;
  if (typeof missingProperty !== 'string') return basePath;
  return basePath === 'input' ? missingProperty : `${basePath}.${missingProperty}`;
}

function formatFieldPath(schemaError: AjvErrorLike): string {
  const rawPath = schemaError.instancePath ?? schemaError.dataPath ?? '';
  const stripped = rawPath.replace(/^[/.]+/, '');
  const normalized = stripped.replace(/\//g, '.');
  return normalized || 'input';
}

